prts.feedbackvariables:
dimnmat(mat,n):= is(length(mat) = n and length(transpose(mat))=n);
validM: dimnmat(ans1,n);
validD: dimnmat(ans2,n);
studM: if(validM) then ans1 else zeromatrix(n,n);
studD: if(validD) then ans2 else zeromatrix(n,n);

isdiag: diagomatrixp(studD);
isorth: is(simplify(studM.conjugate(transpose(studM)))=ident(n));

studMAMt: mysimp(conjugate(transpose(studM)).A.studM);
goodans: is(studMAMt=mysimp(studD));
